    if (!ctx.patches) {
        jit->buf.failed = 1;
        return NULL;
    }
    ctx.patches->count = 0;
    ctx.func_idx = func_idx;
    ctx.func_bc_start = bc_start;
    ctx.func_bc_end = bc_end;

