void cvm_jit_stats(const CvmState *vm) {
    if (!vm->jit) return;
    fprintf(stderr, "cvm jit: %zu functions compiled, %zu bytes of native code\n",
            JIT_STATE(vm)->num_funcs_compiled, JIT_STATE(vm)->buf.size);
