    }
    case OP_LEA_DATA: {
        uint32_t o = cvm_ops_ru32(code, v->code_size, off + 1);
        if (o > v->data_size) {
            char msg[96];
            snprintf(msg, sizeof(msg),
                     "data offset %u out of range (data=%u) at 0x%04zx",
                     o, v->data_size, off);
